// The review subcommand re-evaluates one decision preserved in an audit
// archive after the service instance that decided it has ended. It never
// talks to a running service and never creates or restores a Store: the
// decision is recomputed purely from the saved record's request, the
// historical policy version carried in records before it, and a checkpoint
// the caller retained separately from the archive.
package main

import (
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

// Exit codes for the review command:
//
//   - 0: a full review was produced and the complete report was written
//     without error, including a legitimate archive whose original and
//     recomputed decisions disagree.
//   - 2: the invocation itself is wrong (missing/invalid arguments, the
//     archive file cannot be read).
//   - 1: the material or target cannot support a review (an invalid or
//     chain-broken archive, a missing or non-decision target, a historical
//     policy version that cannot be obtained), or the review report could
//     not be written out in full.
const (
	reviewExitOK     = 0
	reviewExitFailed = 1
	reviewExitUsage  = 2
)

// reviewInputs holds everything the review command needs from the caller.
type reviewInputs struct {
	archivePath string
	org         string
	seq         int
	endSeq      int
	fingerprint string
	// json selects machine-readable JSON output instead of the default text
	// report. The review itself is identical either way: the same archive
	// validation and the same historical recheck, never a re-submitted
	// request.
	json bool
}

func reviewHelp(w io.Writer) {
	fmt.Fprint(w, `usage: darksafe review --archive FILE --org ORG --seq N \
                      --end-seq N --fingerprint HEX

Review one access decision saved in an audit archive, long after the
service instance that made the decision has ended. No running service is
contacted and no policy store is created or restored; the decision is
recomputed offline from the archived material alone. The archived decision
is never re-submitted as a new access request.

Required inputs:
  --archive FILE       path to the audit archive written by
                       EncodeAuditArchive (the complete export, not a
                       subject-filtered page or a fragment)
  --org ORG            organization name the archive belongs to; it must
                       match the organization bound into the records
  --seq N              positive sequence number of the decision record to
                       review (organization-local, starting at 1)
  --end-seq N          end sequence of the checkpoint retained separately
                       from the archive (0 for an organization with no
                       records); must not be negative
  --fingerprint HEX    checkpoint fingerprint retained separately from the
                       archive (64 hexadecimal SHA-256 characters)
  --json               emit the review as one complete JSON object on
                       stdout instead of the text report. The object gives
                       "target_sequence", "original" and "recomputed"
                       decisions (each with "allowed", "reason",
                       "matched_policies" in original order, and
                       "policy_version"), and "consistent". A valid UTF-8
                       string is a JSON string; a string that is not valid
                       UTF-8 is the object {"base64": "<standard base64 of
                       the exact bytes>"}, so a lone 0xFF, a lone 0xFE and a
                       real U+FFFD never collapse together and every string's
                       original bytes can be recovered. A nil and an empty
                       matched list both render as []. A failure before the
                       report is written leaves stdout empty and the reason on
                       stderr only; if stdout refuses the report or accepts
                       only part of it, any accepted prefix stays in place,
                       the command exits 1 and the output failure is reported
                       on stderr, never retried in another format.

The checkpoint carried inside the archive is informational only: validation
always uses --end-seq/--fingerprint supplied here. Even when --seq points at
an early record, every archived record is checked; a corrupted or missing
later record, or any mismatch with the retained checkpoint, fails the whole
review with no partial output.

The request is replayed strictly against the policy version the recorded
decision actually used; later publishes or rollbacks present in the archive
are never substituted. A chain that is valid but whose original and
recomputed decisions disagree is still printed in full and exits 0; the
disagreement is shown explicitly rather than reported as file damage.

Strings may contain spaces, control characters or non-UTF-8 bytes; the text
report uses Go-style quoting, while --json uses the JSON string /
{"base64": ...} rule described above, and both keep different raw bytes
distinguishable. This command only reads the named archive: it neither
rewrites it nor appends audit records.

Exit codes: 0 complete report written without error (decisions may
disagree), 1 archive or target invalid / historical version unavailable /
review report could not be written out in full, 2 bad arguments or
unreadable file. --json changes none of these.

Example:
  (materials produced by examples/offline_review; seq 1 is the
  policy publish record, seq 2 is the read decision being reviewed)
  darksafe review --archive acme-factory.audit \
      --org 'acme factory' --seq 2 --end-seq 2 \
      --fingerprint 04b274dbb4cf039bbb4b78f5ee5aae03278d2c34833fe87fecb13ade51ef5299

  add --json to get the same review as one JSON object:
  darksafe review --json --archive acme-factory.audit \
      --org 'acme factory' --seq 2 --end-seq 2 \
      --fingerprint 04b274dbb4cf039bbb4b78f5ee5aae03278d2c34833fe87fecb13ade51ef5299
`)
}

// parseReviewArgs parses review arguments. flags is an injectable args slice
// so tests can drive the command directly. The first element of args is the
// subcommand name ("review"). --help/-h/-help set wantHelp.
func parseReviewArgs(args []string) (in reviewInputs, wantHelp bool, err error) {
	haveSeq, haveEndSeq := false, false
	for i := 1; i < len(args); i++ {
		arg := args[i]
		value := ""
		hasValue := false
		switch {
		case arg == "--help" || arg == "-h" || arg == "-help":
			return reviewInputs{}, true, nil
		case len(arg) > 2 && arg[:2] == "--":
			// Accept both --flag value and --flag=value.
			if eq := strings.IndexByte(arg, '='); eq >= 0 {
				value = arg[eq+1:]
				hasValue = true
				arg = arg[:eq]
			}
		default:
			return reviewInputs{}, false, fmt.Errorf("unexpected argument %q", arg)
		}

		take := func() (string, error) {
			if hasValue {
				return value, nil
			}
			if i+1 >= len(args) {
				return "", fmt.Errorf("flag %s requires a value", arg)
			}
			i++
			return args[i], nil
		}

		switch arg {
		case "--archive":
			v, err := take()
			if err != nil {
				return reviewInputs{}, false, err
			}
			in.archivePath = v
		case "--org":
			v, err := take()
			if err != nil {
				return reviewInputs{}, false, err
			}
			in.org = v
		case "--seq":
			v, err := take()
			if err != nil {
				return reviewInputs{}, false, err
			}
			n, perr := strconv.Atoi(v)
			if perr != nil {
				return reviewInputs{}, false, fmt.Errorf("--seq must be an integer, got %q", v)
			}
			in.seq = n
			haveSeq = true
		case "--end-seq":
			v, err := take()
			if err != nil {
				return reviewInputs{}, false, err
			}
			n, perr := strconv.Atoi(v)
			if perr != nil {
				return reviewInputs{}, false, fmt.Errorf("--end-seq must be an integer, got %q", v)
			}
			in.endSeq = n
			haveEndSeq = true
		case "--fingerprint":
			v, err := take()
			if err != nil {
				return reviewInputs{}, false, err
			}
			in.fingerprint = v
		case "--json":
			// Bare --json enables JSON output; --json=value accepts the
			// usual boolean spellings. No value is ever consumed from the
			// following token, so "--json --seq 2" keeps working.
			switch {
			case !hasValue:
				in.json = true
			default:
				b, perr := strconv.ParseBool(value)
				if perr != nil {
					return reviewInputs{}, false, fmt.Errorf("--json must be a boolean, got %q", value)
				}
				in.json = b
			}
		default:
			return reviewInputs{}, false, fmt.Errorf("unknown review flag %q", arg)
		}
	}

	if in.archivePath == "" {
		return reviewInputs{}, false, errors.New("--archive is required")
	}
	if in.org == "" {
		return reviewInputs{}, false, errors.New("--org is required")
	}
	if !haveSeq {
		return reviewInputs{}, false, errors.New("--seq is required")
	}
	if in.seq <= 0 {
		return reviewInputs{}, false, fmt.Errorf("--seq must be a positive integer, got %d", in.seq)
	}
	if !haveEndSeq {
		return reviewInputs{}, false, errors.New("--end-seq is required")
	}
	if in.endSeq < 0 {
		return reviewInputs{}, false, fmt.Errorf("--end-seq must not be negative, got %d", in.endSeq)
	}
	if in.fingerprint == "" {
		return reviewInputs{}, false, errors.New("--fingerprint is required")
	}
	return in, false, nil
}

// runReview executes one offline review and returns the process exit code.
// stdout/stderr are injectable so the command stays testable; args is the
// full argument vector including the leading "review".
func runReview(args []string, stdout, stderr io.Writer) int {
	in, wantHelp, err := parseReviewArgs(args)
	if wantHelp {
		reviewHelp(stdout)
		return reviewExitOK
	}
	if err != nil {
		fmt.Fprintf(stderr, "review: %s\n", err)
		return reviewExitUsage
	}

	archive, err := os.ReadFile(in.archivePath)
	if err != nil {
		fmt.Fprintf(stderr, "review: cannot read archive %q: %v\n", in.archivePath, err)
		return reviewExitUsage
	}

	cp := darksafe.Checkpoint{Org: in.org, EndSeq: in.endSeq, Fingerprint: in.fingerprint}
	// Decode and chain validation are one stage: the archive is checked
	// against the retained checkpoint exactly once here, and the review
	// below replays the target from that already-verified material rather
	// than walking the whole chain a second time.
	material, err := darksafe.DecodeVerifiedAuditArchive(archive, in.org, cp)
	if err != nil {
		fmt.Fprintf(stderr, "review: archive validation failed: %v\n", err)
		return reviewExitFailed
	}
	review, err := darksafe.RecheckVerifiedDecisionOffline(material, in.seq)
	if err != nil {
		fmt.Fprintf(stderr, "review: %v\n", err)
		return reviewExitFailed
	}

	// Render both formats fully before touching stdout: a render failure must
	// not leave partial output, and every earlier failure path already
	// returned with stdout untouched.
	var payload []byte
	if in.json {
		payload, err = renderReviewJSON(review)
		if err != nil {
			fmt.Fprintf(stderr, "review: cannot encode result as JSON: %v\n", err)
			return reviewExitFailed
		}
	} else {
		var buf strings.Builder
		printReview(&buf, review)
		payload = []byte(buf.String())
	}

	// Success requires the WHOLE report to actually land. A receiver may
	// accept some bytes and then refuse the rest, or report a short write
	// with no error; neither may be mistaken for a completed review merely
	// because the archive validated and the decision recomputed. Whatever
	// prefix the receiver already accepted stays there (it cannot be
	// unwritten), but nothing more is appended afterwards.
	n, werr := stdout.Write(payload)
	if werr != nil {
		fmt.Fprintf(stderr, "review: failed to write review report: %v\n", werr)
		return reviewExitFailed
	}
	if n < len(payload) {
		fmt.Fprintf(stderr,
			"review: review report output incomplete: wrote %d of %d bytes\n",
			n, len(payload))
		return reviewExitFailed
	}
	return reviewExitOK
}

// printReview renders the target sequence, both full decisions and the
// consistency verdict. Every potentially non-UTF-8 string is emitted with
// %q (Go quoting): a lone 0xFF renders as "\xff", 0xFE as "\xfe" and a real
// U+FFFD as "�", so distinct raw bytes never collapse onto one glyph.
func printReview(w io.Writer, r darksafe.OfflineDecisionReview) {
	fmt.Fprintf(w, "target sequence: %d\n", r.Seq)
	fmt.Fprintln(w, "original decision:")
	printDecision(w, r.Original)
	fmt.Fprintln(w, "recomputed decision:")
	printDecision(w, r.Recomputed)
	if r.Consistent {
		fmt.Fprintln(w, "consistent: yes")
	} else {
		fmt.Fprintln(w, "consistent: no (original and recomputed decisions differ)")
	}
}

func printDecision(w io.Writer, d darksafe.Decision) {
	fmt.Fprintf(w, "  allowed: %v\n", d.Allowed)
	fmt.Fprintf(w, "  reason: %q\n", d.Reason)
	fmt.Fprintf(w, "  matched policies: %s\n", formatMatched(d.Matched))
	fmt.Fprintf(w, "  policy version: %d\n", d.Version)
}

// formatMatched quotes each matched policy identifier byte-for-byte. A nil
// and an empty list mean the same set of hits but keep distinguishable
// spellings, mirroring the library's own nil-versus-empty preservation.
func formatMatched(matched []string) string {
	if matched == nil {
		return "[]"
	}
	out := "["
	for i, id := range matched {
		if i > 0 {
			out += ", "
		}
		out += strconv.Quote(id)
	}
	return out + "]"
}

// This file implements offline review of a single audited decision. It
// works solely from exported audit material: the complete record export,
// the separately retained checkpoint, and a target sequence. No Store is
// created or restored, so an organization can confirm why an access was
// allowed or denied long after the service instance that decided it has
// ended.
//
// The complete input must first validate as an audit chain. The policy
// version a decision actually used is recovered exclusively from policy
// change records preceding that decision within the same organization's
// export; later publishes or rollbacks, and a wider later export, cannot
// change the recomputed result.
//
// A review that already holds the material as decoded records
// (RecheckDecisionOffline) and one that starts from an archive file
// (DecodeAuditArchive followed by a review) historically each ran the full
// VerifyAudit chain check on their own, so `darksafe review` validated the
// same material twice per invocation. The two stages now share one pass:
// VerifyAudit runs exactly once per review, its result is carried in an
// unexported VerifiedAuditMaterial, and the review replays the target from
// that already-verified material without re-checking the chain. The
// standalone entry points keep validating their own inputs, so neither
// requires the caller to have run another entry point first.
package darksafe

import "fmt"

// OfflineDecisionReview compares the decision stored in an audited record
// with a decision recomputed purely from the exported material.
type OfflineDecisionReview struct {
	// Seq is the reviewed decision record's sequence.
	Seq int
	// Original is the decision preserved in the audited record.
	Original Decision
	// Recomputed is the decision evaluated again offline from the saved
	// request and the policy version it originally used.
	Recomputed Decision
	// Consistent reports whether both decisions agree on every field
	// (allowance, reason, matched policies and version), treating a nil
	// matched list and an empty matched list as the same.
	Consistent bool
}

// VerifiedAuditMaterial is an export that has passed the complete
// VerifyAudit chain check against the checkpoint it carries. It is the
// boundary between one validation and the review: an entry point that has
// just validated the material hands it to RecheckVerifiedDecisionOffline,
// and the review replays the target without validating the chain a second
// time.
//
// It is intentionally unexported: it can only be produced by this package's
// own validating entry points (verifyAuditMaterial, reached from
// RecheckDecisionOffline, DecodeAuditArchive and DecodeVerifiedAuditArchive),
// never from a caller's assertion. It carries no memo that survives the
// call that produced it, so modified material or a different checkpoint
// always forces a fresh validation; the embedded records are the caller's
// and stay owned by the caller.
type VerifiedAuditMaterial struct {
	org     string
	records []AuditRecord
	cp      Checkpoint
}

// verifyAuditMaterial validates the whole export exactly as VerifyAudit
// does and, on success, returns it as VerifiedAuditMaterial. It is the
// single place the chain check is performed on the offline review path; a
// failure returns no material, so a later stage can never review records
// that did not validate.
func verifyAuditMaterial(org string, records []AuditRecord, cp Checkpoint) (VerifiedAuditMaterial, error) {
	if verifyAuditObserver != nil {
		verifyAuditObserver()
	}
	if err := VerifyAudit(org, records, cp); err != nil {
		return VerifiedAuditMaterial{}, err
	}
	return VerifiedAuditMaterial{org: org, records: records, cp: cp}, nil
}

// RecheckVerifiedDecisionOffline re-evaluates one decision record from
// material a preceding stage has already chain-validated as one unit
// (verifyAuditMaterial or DecodeVerifiedAuditArchive). It does not run the
// chain check again: one review performs one complete chain validation, and
// tampering anywhere is rejected before this stage is reached. All target
// and replay guarantees are otherwise identical to
// RecheckDecisionOffline's: ErrAuditNotFound for a non-positive or absent
// target sequence, ErrAuditNotADecision when the target is a policy change
// record, and ErrVersionNotFound when the version the decision names has no
// change record before the target (including content that appears only
// after it); a newer version is never substituted. The call is read-only
// and the returned decisions are detached from the material's slices.
func RecheckVerifiedDecisionOffline(m VerifiedAuditMaterial, seq int) (OfflineDecisionReview, error) {
	return recheckVerifiedOffline(m, seq)
}

// recheckVerifiedOffline is the shared review body. It takes an unexported
// verified-material value so only this package's validating stages can
// reach the already-validated path; standalone RecheckDecisionOffline
// validates first and then calls it just as the combined archive flow does.
func recheckVerifiedOffline(m VerifiedAuditMaterial, seq int) (OfflineDecisionReview, error) {
	org, records := m.org, m.records
	if seq < 1 {
		return OfflineDecisionReview{}, fmt.Errorf("%w: sequence %d", ErrAuditNotFound, seq)
	}
	if seq > len(records) {
		return OfflineDecisionReview{}, fmt.Errorf("%w: export ends at %d, no sequence %d", ErrAuditNotFound, len(records), seq)
	}
	rec := &records[seq-1]
	if rec.Kind != AuditDecision || rec.Decision == nil {
		return OfflineDecisionReview{}, fmt.Errorf("%w: sequence %d is %s", ErrAuditNotADecision, seq, rec.Kind)
	}

	original := cloneDecisionValue(rec.Decision.Decision)
	req := rec.Decision.Request
	// Detach the request list by non-nil rather than by length: a non-nil
	// empty role list with spare capacity must not be shared back with the
	// caller's material, even though evaluation never reads any element.
	req.Subject.Roles = cloneStrings(req.Subject.Roles)
	version := original.Version

	// The version's full content must travel in a same-organization policy
	// change record positioned before the decision. The replay core resolves
	// the version before replaying any request rule, so a request the
	// envelope rejects cannot mask a missing or later-only version.
	resolve := func(want int) versionPolicies {
		if policies, found := policiesBefore(records, seq-1, want); found {
			return versionPolicies{policies: policies}
		}
		if _, later := policiesBefore(records, len(records), want); later {
			return versionPolicies{status: replayVersionAfterTarget}
		}
		return versionPolicies{status: replayVersionAbsent}
	}
	recomputed, status := replayRecordedDecision(org, req, version, resolve)
	switch status {
	case replayVersionAfterTarget:
		return OfflineDecisionReview{}, fmt.Errorf(
			"%w: decision at sequence %d used version %d, whose change record appears only after it",
			ErrVersionNotFound, seq, version)
	case replayVersionAbsent:
		return OfflineDecisionReview{}, fmt.Errorf(
			"%w: decision at sequence %d used version %d, which has no policy change record in the export",
			ErrVersionNotFound, seq, version)
	}

	return OfflineDecisionReview{
		Seq:        seq,
		Original:   original,
		Recomputed: recomputed,
		Consistent: decisionsEqual(original, recomputed),
	}, nil
}

// RecheckDecisionOffline re-evaluates one decision record offline. org is
// the organization name, records is its complete export starting at
// sequence 1 (a valid prefix is sufficient when paired with its own
// checkpoint), cp is the separately saved checkpoint, and seq identifies
// the decision record to review. The call is read-only: it neither mutates
// the supplied material nor appends audit records, and the returned
// decisions are detached from the input slices.
//
// The entire export is chain-validated in this call before any result is
// produced; tampering anywhere, including in records after the target,
// fails the review. The caller does not need to have validated the
// material through another entry point first: standalone callers receive
// the exact same guarantees DecodeAuditArchive gives, and validation is
// always based on this call's material, organization and checkpoint — a
// previous validation is never reused after the material changes or the
// checkpoint changes. Distinguishable errors follow the other audit entry
// points: ErrMissingOrganization for an empty organization, ErrAuditNotFound
// for a non-positive or absent target sequence, and ErrAuditNotADecision
// when the target is a policy change record. When the saved decision names
// a policy version whose full content has no change record before the
// target, ErrVersionNotFound is returned; a newer version is never
// substituted, and a request the envelope would reject never masks the
// missing version.
//
// The fingerprint only proves the material matches its checkpoint; it
// cannot stand in for evaluating the request itself. So even when the
// declared version exists and carries an otherwise matching allow policy,
// the recomputation enforces the same request rules as the online
// decision: a disabled subject, an organization mismatch, a missing
// subject or resource organization or identifier, an empty action, and an
// illegal resource scope all deny, with the same reasons and precedence as
// Decide. Such a rejection uses no policies, so the recomputed decision
// reports version 0 with no matched policies; it is then compared field by
// field with the preserved original and may come back inconsistent.
func RecheckDecisionOffline(org string, records []AuditRecord, cp Checkpoint, seq int) (OfflineDecisionReview, error) {
	if org == "" {
		return OfflineDecisionReview{}, ErrMissingOrganization
	}
	// Validate the whole export first. A subject-filtered page, a fragment
	// missing the beginning, or a checkpoint that does not pin the records
	// all fail here, as does any corruption after the target.
	m, err := verifyAuditMaterial(org, records, cp)
	if err != nil {
		return OfflineDecisionReview{}, err
	}
	return recheckVerifiedOffline(m, seq)
}

// policiesBefore searches records[:limit] for the policy change record that
// published version and returns a detached copy of its full content. The
// gapless chain validation guarantees records are in sequence order.
func policiesBefore(records []AuditRecord, limit, version int) ([]Policy, bool) {
	for i := 0; i < limit; i++ {
		r := &records[i]
		if r.Kind != AuditPolicyChange || r.Change == nil {
			continue
		}
		if r.Change.Version == version {
			return append([]Policy(nil), r.Change.Policies...), true
		}
	}
	return nil, false
}

// cloneDecisionValue returns a decision detached from the input's matched
// slice. The list is detached whenever it is non-nil, including a non-nil
// empty list that still has spare capacity, so an append by one receiver
// can never reach another copy.
func cloneDecisionValue(d Decision) Decision {
	d.Matched = cloneStrings(d.Matched)
	return d
}

// decisionsEqual compares every decision field. A nil matched list and an
// empty matched list describe the same set of hits.
func decisionsEqual(a, b Decision) bool {
	if a.Allowed != b.Allowed || a.Reason != b.Reason || a.Version != b.Version {
		return false
	}
	if len(a.Matched) == 0 && len(b.Matched) == 0 {
		return true
	}
	if len(a.Matched) != len(b.Matched) {
		return false
	}
	for i := range a.Matched {
		if a.Matched[i] != b.Matched[i] {
			return false
		}
	}
	return true
}

// verifyAuditObserver, when non-nil, is invoked once for every complete
// VerifyAudit chain validation performed by this package. It exists so
// tests can pin the review flow to a single chain pass per invocation:
// decode and review must share one verification, never validate the same
// material twice. It is a test seam, not production behavior — it is nil in
// normal use and observes nothing about validation's result.
var verifyAuditObserver func()

// SetVerifyAuditObserverForTesting installs observe as the chain-validation
// observer: it is invoked once for every complete VerifyAudit pass the
// package performs. The returned function restores the previous observer
// (the normal nil observer). It exists only so tests can pin the offline
// review flow to one chain validation per command invocation; it has no
// effect on validation itself or on any result.
func SetVerifyAuditObserverForTesting(observe func()) (restore func()) {
	prev := verifyAuditObserver
	verifyAuditObserver = observe
	return func() { verifyAuditObserver = prev }
}

// Command offline_review_example is the end-to-end worked example for
// `darksafe review`. It makes one real access decision, saves the complete
// audit archive and a separately retained checkpoint, and prints the exact
// review command to run next. Everything runs offline in one short program;
// after it exits neither the in-memory Store nor the original access request
// is needed for the review.
//
// Run with:
//
//	go run ./examples/offline_review
//
// The program takes no arguments. It writes two files into the working
// directory:
//
//   - acme-factory.audit: the complete audit archive, sequence 1 (the
//     resource-scoped policy publish) through sequence 2 (the read
//     decision), pinned by the independently saved checkpoint.
//   - acme-factory.checkpoint: the checkpoint kept SEPARATELY from the
//     archive; its end sequence and fingerprint are what a later review
//     must pass on the command line.
//
// Both files are deterministic: the same inputs always produce the same
// bytes and fingerprint.
package main

import (
	"fmt"
	"os"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

// Archive and checkpoint filenames for the worked example.
const (
	archivePath    = "acme-factory.audit"
	checkpointPath = "acme-factory.checkpoint"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "offline review example: failed:", err)
		os.Exit(1)
	}
}

// run contains the whole worked flow. Every error is fatal because the
// example exists to show the exact sequence of calls: a skipped or tolerated
// failure would leave the user without the materials the printed command
// needs.
func run() error {
	// One organization. The name intentionally contains a space: it is
	// carried verbatim through publish, decision, archive and review, and
	// must be quoted on the review command line.
	const org = "acme factory"

	// One ledger, addressed by both an exact resource id and a scope path.
	// The policy binds subject + read + scope and then narrows to exactly
	// this resource id, so the same subject reading another ledger in the
	// same scope is not authorized by it.
	const (
		ledgerID    = "ledger-2026"
		ledgerScope = "acme/factory/ledger"
		subjectID   = "svc-audit-reader"
	)

	store := darksafe.NewStore()

	// Publish exactly one allow policy: only svc-audit-reader may read,
	// within the ledger scope, ledger-2026 and no other resource. Expected
	// version 0 because nothing has been published for this organization.
	published, err := store.Publish(org, 0, []darksafe.Policy{
		{
			ID:         "p-ledger-read-2026",
			Subject:    subjectID,
			Action:     "read",
			Scope:      ledgerScope,
			Effect:     darksafe.EffectAllow,
			ResourceID: ledgerID,
		},
	})
	if err != nil {
		return fmt.Errorf("publish ledger-read policy as version 1: %w", err)
	}

	// Make one real read decision through the organization-level API. Both
	// organization fields equal the decision organization, the action is
	// read, and the resource id is the one the policy narrows to.
	req := darksafe.OrgRequest{
		SubjectOrg:  org,
		ResourceOrg: org,
		Subject: darksafe.Subject{
			ID:   subjectID,
			Kind: "service",
		},
		Resource: darksafe.Resource{
			ID:    ledgerID,
			Scope: ledgerScope,
		},
		Action: "read",
	}
	decision := store.Decide(org, req)
	if !decision.Allowed {
		// The published allow policy matches this exact subject/scope/
		// resource, so a denial here means the example's own inputs drifted
		// and the archive must not be saved as "the allowed example".
		return fmt.Errorf("expected the read to be allowed, got denial: allowed=%v reason=%q matched=%v version=%d",
			decision.Allowed, decision.Reason, decision.Matched, decision.Version)
	}
	fmt.Printf("online decision: allowed=%v reason=%q matched=%v policy version=%d\n",
		decision.Allowed, decision.Reason, decision.Matched, decision.Version)
	fmt.Printf("published policy became version %d\n", published)

	// Export the complete chain (publish record + decision record) and its
	// pinning checkpoint. AuditExport returns detached copies; when the
	// Store disappears at the end of run(), these are all that remains.
	records, cp, err := store.AuditExport(org, 0)
	if err != nil {
		return fmt.Errorf("export complete audit chain: %w", err)
	}
	if len(records) != 2 {
		// Guard the narrative: seq 1 must be the publish and seq 2 the
		// decision; otherwise the printed --seq would point at the wrong
		// record.
		return fmt.Errorf("expected 2 audit records (publish + decision), got %d", len(records))
	}
	if records[0].Kind != darksafe.AuditPolicyChange || records[1].Kind != darksafe.AuditDecision {
		return fmt.Errorf("unexpected record kinds: seq1=%q seq2=%q", records[0].Kind, records[1].Kind)
	}
	targetSeq := records[1].Seq
	if targetSeq != 2 {
		return fmt.Errorf("decision record should be seq 2 (publish occupies seq 1), got %d", targetSeq)
	}

	// Encode and save the archive.
	archive, err := darksafe.EncodeAuditArchive(org, records, cp)
	if err != nil {
		return fmt.Errorf("encode audit archive: %w", err)
	}
	if err := os.WriteFile(archivePath, archive, 0o600); err != nil {
		return fmt.Errorf("write archive %s: %w", archivePath, err)
	}

	// Save the checkpoint SEPARATELY from the archive. A real retention
	// scheme keeps it elsewhere (another host, a seal, a paper record); here
	// it is simply a second file the archive cannot rewrite. The archive
	// also carries a checkpoint, but it is informational only and can never
	// stand in for this one.
	if err := writeCheckpoint(checkpointPath, cp); err != nil {
		return err
	}

	// Report the saved materials and the exact review command to run next.
	fmt.Println()
	fmt.Println("materials saved:")
	fmt.Printf("  archive:    %s (%d bytes, %d records)\n", archivePath, len(archive), len(records))
	fmt.Printf("  checkpoint: %s  [kept separately]\n", checkpointPath)
	fmt.Println()
	fmt.Println("separately retained checkpoint:")
	fmt.Printf("  org:         %q\n", cp.Org)
	fmt.Printf("  end-seq:     %d\n", cp.EndSeq)
	fmt.Printf("  fingerprint: %s\n", cp.Fingerprint)
	fmt.Println()
	fmt.Println("Now run (the Store and the original request are gone; the review reads")
	fmt.Println("only the saved materials and never re-submits the request):")
	fmt.Println()
	fmt.Println("  go run ./cmd/darksafe review \\")
	fmt.Printf("    --archive %s \\\n", archivePath)
	fmt.Printf("    --org '%s' \\\n", cp.Org)
	fmt.Printf("    --seq %d \\\n", targetSeq)
	fmt.Printf("    --end-seq %d \\\n", cp.EndSeq)
	fmt.Printf("    --fingerprint %s\n", cp.Fingerprint)
	fmt.Println()
	fmt.Println("Two ways to pick the wrong material:")
	fmt.Println()
	fmt.Printf("  (a) --seq %d instead of %d: it points at the policy publish record,\n", records[0].Seq, targetSeq)
	fmt.Println("      which is not a decision; review exits 1 with a distinguishable")
	fmt.Println("      error on stderr and prints nothing on stdout.")
	fmt.Println()
	fmt.Println("  (b) a fingerprint that does not match the archive: same exit code 1,")
	fmt.Println("      same stderr-only, no partial review.")
	return nil
}

// writeCheckpoint writes the independently retained checkpoint as small
// plain text, so the user can read what they are trusting out-of-band:
// one field per line, org quoted byte-for-byte with %q, fingerprint raw.
func writeCheckpoint(path string, cp darksafe.Checkpoint) error {
	content := fmt.Sprintf("org=%q\nend_seq=%d\nfingerprint=%s\n", cp.Org, cp.EndSeq, cp.Fingerprint)
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		return fmt.Errorf("write checkpoint %s: %w", path, err)
	}
	return nil
}

