53	// recoverStringBytes reverses the documented string representation: a JSON
54	// string yields its UTF-8 bytes; a {"base64": ...} object yields the
55	// decoded original bytes.
56	func recoverStringBytes(t *testing.T, v any) []byte {
57		t.Helper()
58		switch s := v.(type) {
59		case string:
60			return []byte(s)
61		case map[string]any:
62			enc, ok := s["base64"].(string)
63			if !ok {
