448		}
449		if recovered["fe"] != "p\xfe" {
450			t.Fatalf("fe recovered as %q", recovered["fe"])
451		}
452		if recovered["uffd"] != "p"+string(rune(0xFFFD)) {
453			t.Fatalf("uffd recovered as %q", recovered["uffd"])
454		}
455		if recovered["ff"] == recovered["fe"] || recovered["ff"] == recovered["uffd"] ||
456			recovered["fe"] == recovered["uffd"] {
457			t.Fatalf("distinct bytes collapsed: %q %q %q", recovered["ff"], recovered["fe"], recovered["uffd"])
458		}
459	}
