1	// Output-failure coverage for `darksafe review`. A review is only successful
2	// when the COMPLETE report landed on stdout without a write error: a receiver
3	// that refuses the write, or one that accepts only some bytes without even
4	// reporting an error, must yield exit 1 and a stderr explanation, regardless
5	// of whether the archive validated and the decision recomputed. These tests
6	// drive runReview with fault-injecting writers in both text and --json modes.
7	package main
8	
9	import (
10		"bytes"
11		"errors"
12		"strings"
13		"testing"
14	)
15	
16	// errSimulatedBrokenStdout stands in for a receiver that explicitly refuses
17	// the write (broken pipe, closed reader, ENOSPC surfaced as an error, ...).
18	var errSimulatedBrokenStdout = errors.New("simulated broken stdout")
19	
20	// rejectingWriter accepts nothing: every Write fails with the sentinel and
21	// reports zero bytes delivered.
22	type rejectingWriter struct{}
23	
24	func (rejectingWriter) Write(p []byte) (int, error) {
25		return 0, errSimulatedBrokenStdout
26	}
27	
28	// partialRejectingWriter accepts up to cap bytes, then refuses the rest with
29	// the sentinel. The accepted prefix stays observable through the embedded
30	// buffer.
31	type partialRejectingWriter struct {
32		got bytes.Buffer
33		cap int
34	}
35	
36	func (w *partialRejectingWriter) Write(p []byte) (int, error) {
37		if w.cap <= 0 {
38			return 0, errSimulatedBrokenStdout
39		}
40		n := min(len(p), w.cap)
41		w.got.Write(p[:n])
42		w.cap -= n
43		if n < len(p) {
44			return n, errSimulatedBrokenStdout
45		}
46		return n, nil
47	}
48	
49	// shortWriter silently accepts at most cap bytes and never returns an error,
50	// modeling a receiver that takes only part of the report (a full disk that
51	// swallowed the error, a consumer that closed early without signaling, etc.).
52	type shortWriter struct {
53		got bytes.Buffer
54		cap int
55	}
56	
57	func (w *shortWriter) Write(p []byte) (int, error) {
58		n := min(len(p), w.cap)
59		w.got.Write(p[:n])
60		w.cap -= n
61		return n, nil
62	}
63	
64	// fullReviewPayload runs one successful review into a buffer and returns the
65	// exact bytes the command tries to deliver, so output-failure tests can
66	// compare any accepted prefix byte-for-byte.
67	func fullReviewPayload(t *testing.T, args []string) []byte {
68		t.Helper()
69		var stdout, stderr bytes.Buffer
70		if code := runReview(args, &stdout, &stderr); code != 0 {
71			t.Fatalf("control review must succeed: code=%d stderr=%q", code, stderr.String())
72		}
73		return append([]byte(nil), stdout.Bytes()...)
74	}
75	
76	// assertOutputFailure checks the common output-failure contract: exit 1, a
77	// non-empty stderr that explains the failed report delivery and never blames
78	// the archive, the target, the historical version or a decision disagreement
79	// for what was purely an output problem.
80	func assertOutputFailure(t *testing.T, code int, stderr string) {
81		t.Helper()
82		if code != 1 {
83			t.Fatalf("an incomplete report must exit 1, got %d; stderr=%q", code, stderr)
84		}
85		if stderr == "" {
86			t.Fatal("an output failure must be explained on stderr")
87		}
88		if !strings.Contains(stderr, "review report") {
89			t.Fatalf("stderr must name the review report output, got %q", stderr)
90		}
91		for _, blame := range []string{
92			"archive validation", "version not found", "not a decision",
93			"decisions differ",
94		} {
95			if strings.Contains(stderr, blame) {
96				t.Fatalf("a pure output failure must not be described as %q: %q", blame, stderr)
97			}
98		}
99	}
100	
101	// TestReviewTextOutputRefused: the text receiver refuses everything, so
102	// stdout stays empty and the concrete write error is preserved on stderr.
103	func TestReviewTextOutputRefused(t *testing.T) {
104		path, cp := fixtureChain(t, "acme")
105		var stderr bytes.Buffer
106		code := runReview(reviewArgs(path, "acme", 2, cp.EndSeq, cp.Fingerprint),
107			rejectingWriter{}, &stderr)
108		assertOutputFailure(t, code, stderr.String())
109		if !strings.Contains(stderr.String(), errSimulatedBrokenStdout.Error()) {
110			t.Fatalf("the concrete write error must be preserved, got %q", stderr.String())
111		}
112	}
113	
114	// TestReviewJSONOutputRefused is the --json counterpart: refusal means an
115	// empty stdout (no partial object) and the preserved write error.
116	func TestReviewJSONOutputRefused(t *testing.T) {
117		path, cp := fixtureChain(t, "acme")
118		var stderr bytes.Buffer
119		code := runReview(jsonReviewArgs(path, "acme", 2, cp.EndSeq, cp.Fingerprint),
120			rejectingWriter{}, &stderr)
121		assertOutputFailure(t, code, stderr.String())
122		if !strings.Contains(stderr.String(), errSimulatedBrokenStdout.Error()) {
123			t.Fatalf("the concrete write error must be preserved, got %q", stderr.String())
124		}
125	}
126	
127	// TestReviewTextOutputShortWriteNoError is the core regression for the text
128	// mode: a receiver that accepts only part of the report AND returns no error
129	// must still fail. The accepted prefix stays exactly as written, with no
130	// appended retries, format switches or success notices.
131	func TestReviewTextOutputShortWriteNoError(t *testing.T) {
132		path, cp := fixtureChain(t, "acme")
133		args := reviewArgs(path, "acme", 2, cp.EndSeq, cp.Fingerprint)
134		full := fullReviewPayload(t, args)
135	
136		const limit = 23 // lands mid-report, mid-line
137		w := &shortWriter{cap: limit}
138		var stderr bytes.Buffer
139		code := runReview(args, w, &stderr)
140		assertOutputFailure(t, code, stderr.String())
141	
142		got := w.got.Bytes()
143		if len(got) != limit {
144			t.Fatalf("accepted prefix length = %d, want %d", len(got), limit)
145		}
146		if !bytes.Equal(got, full[:limit]) {
147			t.Fatalf("accepted prefix altered:\n got %q\nwant %q", got, full[:limit])
148		}
149		if !strings.Contains(stderr.String(), "incomplete") {
150			t.Fatalf("a byte shortage must be reported as incomplete output, got %q", stderr.String())
151		}
152		if !strings.Contains(stderr.String(), "wrote 23 of") {
153			t.Fatalf("stderr must show the short byte count, got %q", stderr.String())
154		}
155		// The cut prefix is mid-report and must not be followed by the closing
156		// consistency verdict (nothing may be appended after the failure).
157		if bytes.Contains(got, []byte("consistent:")) {
158			t.Fatalf("nothing may be appended after the short write:\n%q", got)
159		}
160	}
161	
162	// TestReviewJSONOutputShortWriteNoError is the JSON counterpart: a silent
163	// short write leaves a truncated object (not valid JSON), exits 1 and reports
164	// the shortage without retrying in text form.
165	func TestReviewJSONOutputShortWriteNoError(t *testing.T) {
166		path, cp := fixtureChain(t, "acme")
167		args := jsonReviewArgs(path, "acme", 2, cp.EndSeq, cp.Fingerprint)
168		full := fullReviewPayload(t, args)
169	
170		const limit = 12 // inside the object, far from the closing brace
171		w := &shortWriter{cap: limit}
172		var stderr bytes.Buffer
173		code := runReview(args, w, &stderr)
174		assertOutputFailure(t, code, stderr.String())
175	
176		got := w.got.Bytes()
177		if len(got) != limit || !bytes.Equal(got, full[:limit]) {
178			t.Fatalf("accepted prefix mismatch:\n got %q\nwant %q", got, full[:limit])
179		}
180		if bytes.Contains(got, []byte("target sequence:")) {
181			t.Fatal("a JSON failure must not be retried in text format")
182		}
183		if bytes.Contains(got, []byte("}")) {
184			t.Fatalf("a truncated JSON object must remain truncated, got %q", got)
185		}
